public class BreakoutRoom
{
    public Guid Id { get; } = Guid.NewGuid();
    public Guid MeetingId { get; set; }
    public string Name { get; set; }
    public List<Guid> ParticipantIds { get; } = new();
    public bool IsLocked { get; set; }
}

public class InMeetingChat
{
    public Guid MeetingId { get; set; }
    public List<ChatMessage> Messages { get; } = new();
    public Dictionary<Guid, List<ChatMessage>> ParticipantHistories { get; } = new();
}

public class ChatMessage
{
    public Guid Id { get; } = Guid.NewGuid();
    public Guid SenderId { get; set; }
    public string Text { get; set; }
    public DateTime SentAt { get; } = DateTime.UtcNow;
    public MessageTarget Target { get; set; }
}

public enum MessageTarget { Everyone, Room, Direct }
